inline auto binaryOpResult(const DecimalType<T> & tx, const DecimalType<U> & ty)
{
    UInt32 scale{};
    if constexpr (is_multiply)
        scale = tx.getScale() + ty.getScale();
    else if constexpr (is_division)
        scale = tx.getScale();
    else
        scale = (tx.getScale() > ty.getScale() ? tx.getScale() : ty.getScale());

    if constexpr (sizeof(T) < sizeof(U))
        return DataTypeDecimalTrait<U>(DecimalUtils::max_precision<U>, scale);
    else
        return DataTypeDecimalTrait<T>(DecimalUtils::max_precision<T>, scale);
}

template <bool, bool, typename T, typename U, template <typename> typename DecimalType>
inline DataTypeDecimalTrait<T> binaryOpResult(const DecimalType<T> & tx, const DataTypeNumber<U> &)
{
    return DataTypeDecimalTrait<T>(DecimalUtils::max_precision<T>, tx.getScale());
}

template <bool, bool, typename T, typename U, template <typename> typename DecimalType>
inline DataTypeDecimalTrait<U> binaryOpResult(const DataTypeNumber<T> &, const DecimalType<U> & ty)
{
    return DataTypeDecimalTrait<U>(DecimalUtils::max_precision<U>, ty.getScale());
}

struct DataTypeDecimalTrait
{
    using FieldType = T;
    const UInt32 precision;
    const UInt32 scale;

    DataTypeDecimalTrait(UInt32 precision_, UInt32 scale_)
        : precision(precision_),
          scale(scale_)
    {}

    /// @returns multiplier for U to become T with correct scale
    template <typename U>
    T scaleFactorFor(const DataTypeDecimalTrait<U> & x, bool) const
    {
        if (scale < x.scale)
            throw Exception(ErrorCodes::ARGUMENT_OUT_OF_BOUND, "Decimal result's scale is less than argument's one");
        const UInt32 scale_delta = scale - x.scale; /// scale_delta >= 0
        return DecimalUtils::scaleMultiplier<typename T::NativeType>(scale_delta);
    }
};

/// Calculates result = x * multiplier + delta.
/// If the multiplication or the addition overflows, returns false or throws DECIMAL_OVERFLOW.

using ResultDataType = typename BinaryOperationTraits<Op, LeftDataType, RightDataType>::ResultDataType;


if constexpr (!std::is_same_v<ResultDataType, InvalidType>)
{
    if constexpr (is_int_div || is_int_div_or_zero)
        type_res = std::make_shared<ResultDataType>();
    else if constexpr (IsDataTypeDecimal<LeftDataType> && IsDataTypeDecimal<RightDataType>)
    {
        if constexpr (is_division)
        {
            if (decimalCheckArithmeticOverflow(context_))
            {
                /// Check overflow by using operands scale (based on big decimal division implementation details):
                /// big decimal arithmetic is based on big integers, decimal operands are converted to big integers
                /// i.e. int_operand = decimal_operand*10^scale
                /// For division, left operand will be scaled by right operand scale also to do big integer division,
                /// BigInt result = left*10^(left_scale + right_scale) / right * 10^right_scale
                /// So, we can check upfront possible overflow just by checking max scale used for left operand
                /// Note: it doesn't detect all possible overflow during big decimal division
                if (left.getScale() + right.getScale() > ResultDataType::maxPrecision())
                    throw Exception(ErrorCodes::DECIMAL_OVERFLOW, "Overflow during decimal division");
            }
        }
        ResultDataType result_type = decimalResultType<is_multiply, is_division>(left, right);
        type_res = std::make_shared<ResultDataType>(result_type.getPrecision(), result_type.getScale());
    }
    else if constexpr (((IsDataTypeDecimal<LeftDataType> && IsFloatingPoint<RightDataType>) ||
        (IsDataTypeDecimal<RightDataType> && IsFloatingPoint<LeftDataType>)))
    {
        type_res = std::make_shared<DataTypeFloat64>();
    }
    else if constexpr (IsDataTypeDecimal<LeftDataType>)
    {
        type_res = std::make_shared<LeftDataType>(left.getPrecision(), left.getScale());
    }
    else if constexpr (IsDataTypeDecimal<RightDataType>)
    {
        type_res = std::make_shared<RightDataType>(right.getPrecision(), right.getScale());
    }

struct DivideFloatingImpl
{
    using ResultType = typename NumberTraits::ResultOfFloatingPointDivision<A, B>::Type;
    static const constexpr bool allow_fixed_string = false;
    static const constexpr bool allow_string_integer = false;

    template <typename Result = ResultType>
    static NO_SANITIZE_UNDEFINED Result apply(A a [[maybe_unused]], B b [[maybe_unused]])
    {
        return static_cast<Result>(a) / static_cast<Result>(b);
    }

#if USE_EMBEDDED_COMPILER
    static constexpr bool compilable = true;

    static llvm::Value * compile(llvm::IRBuilder<> & b, llvm::Value * left, llvm::Value * right, bool)
    {
        if (left->getType()->isIntegerTy())
            throw Exception(ErrorCodes::LOGICAL_ERROR, "DivideFloatingImpl expected a floating-point type");
        return b.CreateFDiv(left, right);
    }
#endif
};

template <typename A, typename B>
struct DivideFloatingOrNullImpl : DivideFloatingImpl<A, B>
{
#if USE_EMBEDDED_COMPILER
    static constexpr bool compilable = false;
#endif
};

struct NameDivide { static constexpr auto name = "divide"; };
using FunctionDivideLegacy = BinaryArithmeticOverloadResolver<DivideFloatingImpl, NameDivide>;

/// Keep the serialized AST and the resolved expression under the same name. In particular, key
/// expressions are built by the legacy analyzer while predicates use the query-tree analyzer.

class FunctionDivideExact final : public IFunctionOverloadResolver
{
public:
    static constexpr auto name = "divideExact";

    explicit FunctionDivideExact(ContextPtr context)
        : legacy(FunctionDivideLegacy::create(context))
        , exact(std::make_unique<FunctionToOverloadResolverAdaptor>(createFunctionExactDivide()))
        , integral(FunctionFactory::instance().get("intDiv", context))
    {
    }

    static FunctionOverloadResolverPtr create(ContextPtr context)
    {
        return std::make_unique<FunctionDivideExact>(std::move(context));
    }

    String getName() const override
    {
        return name;
    }
    size_t getNumberOfArguments() const override
    {
        return 2;
    }

    DataTypePtr getReturnTypeImpl(const ColumnsWithTypeAndName & arguments) const override
    {
        return delegate(arguments)->getReturnType(arguments);
    }

    FunctionBasePtr buildImpl(const ColumnsWithTypeAndName & arguments, const DataTypePtr &) const override
    {
        return std::make_shared<FunctionDivideExactBase>(delegate(arguments)->build(arguments));
    }

private:
    const FunctionOverloadResolverPtr & delegate(const ColumnsWithTypeAndName & arguments) const
    {
        const auto left = recursiveRemoveLowCardinality(arguments[0].type);
        const auto right = recursiveRemoveLowCardinality(arguments[1].type);
        const bool constant_unsigned_divisor_fits = isUInt(right) && arguments[1].column
            && isColumnConst(*arguments[1].column)
            && accurateLess((*arguments[1].column)[0], Field(UInt256(1) << (8 * right->getSizeOfValueInMemory() - 1)));
        /// Reuse `intDiv` where its operand casts preserve every input value, including a signed
        /// dividend with a narrower unsigned divisor or a constant that fits its signed cast.
        /// This retains its constant-divisor kernels and monotonicity metadata, under the stable
        /// `divideExact` name, distinct from floating-point `divide`.
        /// Other mixed-sign pairs need checked magnitudes; nullable inputs need to skip masked
        /// overflow and zero-divisor rows.
        if ((isInt(left) && isInt(right)) || (isUInt(left) && isUInt(right))
            || (isInt(left) && isUInt(right)
                && (left->getSizeOfValueInMemory() > right->getSizeOfValueInMemory() || constant_unsigned_divisor_fits)))
        {
            /// `intDiv` disables lazy execution for constant divisors. Keep potentially throwing
            /// constants on the checked path so an enclosing `if` can mask zero and overflow.
            if (arguments[1].column && isColumnConst(*arguments[1].column))
            {
                const auto divisor = (*arguments[1].column)[0];
                if (accurateEquals(divisor, Field(0)) || accurateEquals(divisor, Field(-1)))
                    return exact;
            }
            return integral;
        }
        if (isInteger(removeNullable(left)) && isInteger(removeNullable(right)))
            return exact;
        return legacy;
    }

    FunctionOverloadResolverPtr legacy;
    FunctionOverloadResolverPtr exact;
    FunctionOverloadResolverPtr integral;
};

if (!arguments.empty() && useDefaultImplementationForNulls())
{
    NullPresence null_presence = getNullPresense(arguments);

    if (null_presence.has_null_constant)
    {
        return makeNullable(std::make_shared<DataTypeNothing>());
    }
    if (null_presence.has_nullable)
    {
        Block nested_columns = createBlockWithNestedColumns(arguments);
        auto return_type = getReturnTypeImpl(ColumnsWithTypeAndName(nested_columns.begin(), nested_columns.end()));
        /// If the return type cannot be Nullable (e.g. Array, Tuple, Map),
        /// return it as-is. For null input rows, the function will be evaluated
        /// over the default values of the nested column and produce the corresponding default result
        /// (e.g. an empty array), instead of failing the type check.
        return makeNullableSafe(return_type);
    }
}
